package com.uber.ugroup.api;

import com.uber.ugroup.cache.OffsetCache;
import com.uber.ugroup.config.UGroupProperties;
import java.time.Duration;
import java.time.Instant;
import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Health and status endpoints. */
@RestController
@RequestMapping("/api/v1")
public class HealthController implements HealthIndicator {

  private final UGroupProperties properties;
  private final OffsetCache offsetCache;
  private final Instant startTime;

  public HealthController(UGroupProperties properties, OffsetCache offsetCache) {
    this.properties = properties;
    this.offsetCache = offsetCache;
    this.startTime = Instant.now();
  }

  @GetMapping("/status")
  public ResponseEntity<StatusResponse> getStatus() {
    long uptimeMs = Duration.between(startTime, Instant.now()).toMillis();

    return ResponseEntity.ok(
        new StatusResponse(
            "running",
            uptimeMs,
            properties.getKafka().getClusterName(),
            properties.getKafka().getBootstrapServers(),
            offsetCache.size(),
            Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory(),
            Runtime.getRuntime().maxMemory()));
  }

  @Override
  public Health health() {
    try {
      // Basic health check
      return Health.up()
          .withDetail("cluster", properties.getKafka().getClusterName())
          .withDetail("cacheSize", offsetCache.size())
          .withDetail("uptime", Duration.between(startTime, Instant.now()).toString())
          .build();
    } catch (Exception e) {
      return Health.down(e).build();
    }
  }

  public record StatusResponse(
      String status,
      long uptimeMs,
      String cluster,
      String bootstrapServers,
      long cacheSize,
      long usedMemory,
      long maxMemory) {}
}

