package com.uber.ugroup.api;

import com.uber.ugroup.config.UGroupProperties;
import com.uber.ugroup.fetcher.OffsetFetcher;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.apache.kafka.clients.consumer.OffsetAndMetadata;
import org.apache.kafka.common.PartitionInfo;
import org.apache.kafka.common.TopicPartition;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** REST API for querying consumer group lag. */
@RestController
@RequestMapping("/api/v1")
public class LagController {

  private final OffsetFetcher offsetFetcher;
  private final UGroupProperties properties;

  public LagController(OffsetFetcher offsetFetcher, UGroupProperties properties) {
    this.offsetFetcher = offsetFetcher;
    this.properties = properties;
  }

  /** Get lag for a specific consumer group and topic. */
  @GetMapping("/lag/{group}/{topic}")
  public ResponseEntity<LagResponse> getLag(
      @PathVariable String group, @PathVariable String topic) {

    List<PartitionInfo> partitions = offsetFetcher.partitionsFor(topic);
    if (partitions == null || partitions.isEmpty()) {
      return ResponseEntity.notFound().build();
    }

    List<TopicPartition> topicPartitions =
        partitions.stream().map(pi -> new TopicPartition(topic, pi.partition())).toList();

    Map<TopicPartition, Long> beginningOffsets = offsetFetcher.beginningOffsets(topicPartitions);
    Map<TopicPartition, Long> endOffsets = offsetFetcher.endOffsets(topicPartitions);
    Map<TopicPartition, OffsetAndMetadata> committedOffsets =
        offsetFetcher.listConsumerGroupOffsets(group);

    Map<Integer, PartitionLag> partitionLags = new HashMap<>();
    long totalLag = 0;

    for (TopicPartition tp : topicPartitions) {
      if (!tp.topic().equals(topic)) continue;

      long beginning = beginningOffsets.getOrDefault(tp, 0L);
      long end = endOffsets.getOrDefault(tp, 0L);
      OffsetAndMetadata committed = committedOffsets.get(tp);
      long committedOffset = committed != null ? committed.offset() : -1;

      long lag = committedOffset >= 0 ? Math.max(0, end - committedOffset) : end - beginning;
      totalLag += lag;

      partitionLags.put(
          tp.partition(), new PartitionLag(tp.partition(), beginning, committedOffset, end, lag));
    }

    LagResponse response =
        new LagResponse(
            group, topic, properties.getKafka().getClusterName(), totalLag, partitionLags);

    return ResponseEntity.ok(response);
  }

  /** Get lag summary for a consumer group across all topics. */
  @GetMapping("/lag/{group}")
  public ResponseEntity<GroupLagSummary> getGroupLag(@PathVariable String group) {
    Map<TopicPartition, OffsetAndMetadata> committedOffsets =
        offsetFetcher.listConsumerGroupOffsets(group);

    if (committedOffsets.isEmpty()) {
      return ResponseEntity.notFound().build();
    }

    Map<String, Long> topicLags = new HashMap<>();
    long totalLag = 0;

    // Group by topic
    Map<String, List<TopicPartition>> byTopic = new HashMap<>();
    for (TopicPartition tp : committedOffsets.keySet()) {
      byTopic.computeIfAbsent(tp.topic(), k -> new java.util.ArrayList<>()).add(tp);
    }

    for (Map.Entry<String, List<TopicPartition>> entry : byTopic.entrySet()) {
      String topic = entry.getKey();
      List<TopicPartition> tps = entry.getValue();

      Map<TopicPartition, Long> endOffsets = offsetFetcher.endOffsets(tps);

      long topicLag = 0;
      for (TopicPartition tp : tps) {
        long end = endOffsets.getOrDefault(tp, 0L);
        OffsetAndMetadata committed = committedOffsets.get(tp);
        long committedOffset = committed != null ? committed.offset() : 0;
        topicLag += Math.max(0, end - committedOffset);
      }

      topicLags.put(topic, topicLag);
      totalLag += topicLag;
    }

    return ResponseEntity.ok(
        new GroupLagSummary(group, properties.getKafka().getClusterName(), totalLag, topicLags));
  }

  // Response DTOs

  public record LagResponse(
      String group,
      String topic,
      String cluster,
      long totalLag,
      Map<Integer, PartitionLag> partitions) {}

  public record PartitionLag(
      int partition, long beginningOffset, long committedOffset, long endOffset, long lag) {}

  public record GroupLagSummary(
      String group, String cluster, long totalLag, Map<String, Long> topicLags) {}
}

